package com.example.prestamolab_ctma.data.repository
import com.example.prestamolab_ctma.model.*
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
class InMemoryPrestamoRepository:PrestamoRepository{
 private val equipos=mutableListOf(Equipo(1,"Multímetro digital",CategoriaEquipo.ELECTRONICA,EstadoEquipo.DISPONIBLE,"Instrumento para medir voltaje, corriente y resistencia."),Equipo(2,"Kit de electrónica",CategoriaEquipo.ELECTRONICA,EstadoEquipo.DISPONIBLE,"Kit para prácticas básicas de circuitos."))
 private val solicitudes=mutableListOf<SolicitudPrestamo>(); private val ef=MutableStateFlow(equipos.toList());private val sf=MutableStateFlow(solicitudes.toList());private var next=1
 override suspend fun inicializar()=Unit;override fun observarEquipos():Flow<List<Equipo>> =ef;override fun observarSolicitudes():Flow<List<SolicitudPrestamo>> =sf;override suspend fun obtenerEquipo(id:Int)=equipos.find{it.id==id};override suspend fun obtenerSolicitud(id:Int)=solicitudes.find{it.id==id}
 override suspend fun crearSolicitud(equipoId:Int,destino:String,proposito:String,duracionHoras:Int):Result<SolicitudPrestamo>{val e=obtenerEquipo(equipoId)?:return Result.failure(IllegalArgumentException("No existe"));if(e.estado!=EstadoEquipo.DISPONIBLE)return Result.failure(IllegalStateException("No disponible"));if(!destinoValido(destino)||!propositoValido(proposito)||!duracionValida(duracionHoras))return Result.failure(IllegalArgumentException("Datos inválidos"));val s=SolicitudPrestamo(next++,equipoId,destino,proposito,duracionHoras,EstadoSolicitud.SOLICITADA);solicitudes+=s;equipos[equipos.indexOf(e)]=e.copy(estado=EstadoEquipo.RESERVADO);publish();return Result.success(s)}
 override suspend fun cancelarSolicitud(id:Int):Result<Unit>{val s=obtenerSolicitud(id)?:return Result.failure(IllegalArgumentException("No existe"));solicitudes[solicitudes.indexOf(s)]=s.copy(estado=EstadoSolicitud.CANCELADA);obtenerEquipo(s.equipoId)?.let{equipos[equipos.indexOf(it)]=it.copy(estado=EstadoEquipo.DISPONIBLE)};publish();return Result.success(Unit)}
 override suspend fun guardarEvidencia(id:Int,uri:String,nombre:String)=Result.success(Unit);override suspend fun guardarUbicacion(id:Int,latitud:Double,longitud:Double)=Result.success(Unit);override suspend fun sincronizar()=Result.success(Unit);private fun publish(){ef.value=equipos.toList();sf.value=solicitudes.toList()}
}
